using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient = new();

    [Description("Search the web for information on a topic. Returns relevant snippets from Wikipedia.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&format=json&srlimit=5&utf8=1";

            var json = await _httpClient.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);

            var results = doc.RootElement
                .GetProperty("query")
                .GetProperty("search");

            var snippets = new List<string>();
            foreach (var result in results.EnumerateArray())
            {
                var title = result.GetProperty("title").GetString();
                // Strip HTML tags from the snippet
                var snippet = System.Text.RegularExpressions.Regex.Replace(
                    result.GetProperty("snippet").GetString() ?? "", "<.*?>", "");
                snippets.Add($"• {title}: {snippet}");
            }

            return snippets.Count > 0
                ? $"Search results for \"{query}\":\n{string.Join("\n", snippets)}"
                : $"No results found for \"{query}\".";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Fetch the summary of a specific Wikipedia article by its exact title.")]
    public async Task<string> FetchArticleSummary(
        [Description("The exact title of the Wikipedia article")] string title)
    {
        try
        {
            var encoded = Uri.EscapeDataString(title);
            var url = $"https://en.wikipedia.org/api/rest_v1/page/summary/{encoded}";

            _httpClient.DefaultRequestHeaders.UserAgent.Clear();
            _httpClient.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

            var json = await _httpClient.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);

            var extract = doc.RootElement.GetProperty("extract").GetString();
            return string.IsNullOrWhiteSpace(extract)
                ? $"No summary available for \"{title}\"."
                : $"Summary of \"{title}\":\n{extract}";
        }
        catch (Exception ex)
        {
            return $"Failed to fetch article \"{title}\": {ex.Message}";
        }
    }
}

using System.ComponentModel;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

public sealed class NoteTool
{
    private readonly List<(string Tag, string Content)> _notes = [];

    [Description("Save a research note with a short tag for organization. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("A short tag or category for the note (e.g. 'definition', 'history', 'key-fact')")] string tag,
        [Description("The note content to save")] string content)
    {
        _notes.Add((tag, content));
        return $"Note #{_notes.Count} saved under [{tag}].";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"Note #{i + 1} [{n.Tag}]: {n.Content}"));
    }
}

