using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using OpenAI;
using ResearchAgent.Tools;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// Set up DI and register the chat client
var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

// Create tool instances
var webSearch = new WebSearchTool();
var noteTool = new NoteTool();

// Register tools via AIFunctionFactory
var tools = new AIFunction[]
{
    AIFunctionFactory.Create(webSearch.SearchWeb, nameof(webSearch.SearchWeb)),
    AIFunctionFactory.Create(webSearch.FetchArticleSummary, nameof(webSearch.FetchArticleSummary)),
    AIFunctionFactory.Create(noteTool.SaveNote, nameof(noteTool.SaveNote)),
    AIFunctionFactory.Create(noteTool.GetAllNotes, nameof(noteTool.GetAllNotes)),
};

// Create agent with ChatClientAgent from Microsoft.Agents.AI
var agent = new ChatClientAgent(
    chatClient,
    "ResearchAgent",
    """
    You are a research agent. Your job is to thoroughly research a topic the user provides.

    Follow this workflow:
    1. Search the web for the topic to find relevant information.
    2. For promising results, fetch the article summary to get more detail.
    3. Save important findings as notes using descriptive tags.
    4. Repeat searches with different queries to cover multiple angles of the topic.
    5. After gathering enough information (at least 3-5 notes), retrieve all notes and
       produce a well-structured summary with key findings organized by theme.

    Always cite which articles your information came from.
    """);

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔍 Research Agent v1.0         ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or       ║");
Console.WriteLine("║  type 'quit' to exit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine($"Researching \"{topic}\"...");
    Console.ResetColor();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
    };

    var options = new AgentInvokeOptions
    {
        MaximumIterations = 10,
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            Tools = [.. tools],
            ToolMode = ChatToolMode.Auto,
        },
    };

    try
    {
        string finalResponse = "";
        await foreach (var message in agent.InvokeAsync(messages, options))
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
            {
                finalResponse = message.Text;
            }
        }

        Console.WriteLine();
        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("═══ Research Summary ═══");
        Console.ResetColor();
        Console.WriteLine(finalResponse);
        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }
}

