 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 const string modelId = "gpt-4o-mini-2024-07-18";

 // Build the chat client through MEAI abstraction
 IChatClient chatClient = new OpenAIClient(apiKey)
     .GetChatClient(modelId)
     .AsIChatClient();

 // Create tool instances
 var webSearch = new WebSearchTool();
 var noteTool = new NoteTool();

 // Register tools via AIFunctionFactory
 var tools = new List<AITool>
 {
     AIFunctionFactory.Create(webSearch.SearchWeb),
     AIFunctionFactory.Create(webSearch.FetchArticleSummary),
     AIFunctionFactory.Create(noteTool.SaveNote),
     AIFunctionFactory.Create(noteTool.GetAllNotes),
 };

 // Create agent with ChatClientAgent from Microsoft.Agents.AI
 var agent = new ChatClientAgent(
     chatClient,
     instructions: """
         You are a research agent. Your job is to thoroughly research a topic the user provides.

         Follow this workflow:
         1. Search the web for the topic to find relevant information.
         2. For promising results, fetch the article summary to get more detail.
         3. Save important findings as notes using descriptive tags.
         4. Repeat searches with different queries to cover multiple angles of the topic.
         5. After gathering enough information (at least 3-5 notes), retrieve all notes and
            produce a well-structured summary with key findings organized by theme.

         Always cite which articles your information came from.
         """,
     name: "ResearchAgent",
     description: "An agent that researches topics using web search and note-taking tools",
     tools: tools);

 Console.WriteLine("╔══════════════════════════════════════╗");
 Console.WriteLine("║       🔍 Research Agent v1.0         ║");
